import type { CliContext } from "./engine.ts";

export type LabId = "router-foundation" | "switch-foundation";
export type LabPhase = "access" | "identity" | "security" | "services" | "interfaces" | "verification";
export type LabContext = CliContext;

export interface LabContentStep {
  id: string;
  conceptId: string;
  phase: LabPhase;
  context: LabContext;
  command: string;
  task: string;
  why: string;
  hint1: string;
  hint2: string;
  effect: string;
  verify: string;
  interpretation: string;
  commonFailure: string;
  recovery: string;
  nextContext?: LabContext;
  nextHostname?: "R1" | "SW1";
  output?: readonly string[];
  sensitiveArgumentNames?: readonly string[];
}

export interface LabContentDefinition {
  id: LabId;
  number: 2 | 3;
  title: string;
  summary: string;
  deviceProfile: "router-ios-xe" | "catalyst-l2";
  initialHostname: "Router" | "Switch";
  stages: readonly LabPhase[];
  steps: readonly LabContentStep[];
}

type StepOptions = Partial<Pick<LabContentStep,
  "hint1" | "hint2" | "interpretation" | "commonFailure" | "nextContext" | "nextHostname" | "output" | "sensitiveArgumentNames"
>>;

const firstKeyword = (command: string): string => command.trim().split(/\s+/u)[0] ?? "relevant";
const withoutPasteableCommand = (value: string, command: string): string => value.replace(
  new RegExp(command.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&"), "igu"),
  "the requested operation",
);

const defaultHint2 = (context: LabContext, command: string, task: string, why: string): string => {
  const family = firstKeyword(command);
  if (/\b(?:secret|key|password)\b/iu.test(command)) {
    return `At the ${context} prompt, use the ${family} family and enter the supplied case-sensitive training value only when requested.`;
  }
  if (/^(?:show|ping|ssh|traceroute|dir)\b/iu.test(command)) {
    return `At the ${context} prompt, use the ${family} inspection or test family to answer this one question: ${task}`;
  }
  if (/^(?:exit|end|enable|disable|configure|interface|line|router|vlan|radius|aaa group|ip access-list|ip dhcp pool)\b/iu.test(command)) {
    return `At the ${context} prompt, use the ${family} navigation family for “${task}” The next scope matters because ${why.charAt(0).toLocaleLowerCase("en-GB")}${why.slice(1)}`;
  }
  return `At the ${context} prompt, use the ${family} configuration family and supply only the target or value named here: ${task}`;
};

const defaultInterpretation = (task: string, effect: string, verify: string): string =>
  `Expected cause and effect: ${effect} Evidence for “${task}”: ${verify}`;

const defaultCommonFailure = (
  phase: LabPhase,
  task: string,
  effect: string,
  recovery: string,
): string => {
  if (phase === "verification") {
    return `Read-only output is not success by itself. If it does not prove “${effect}”, keep the task open and investigate the disagreeing field.`;
  }
  if (/^(?:Return|Move|Enter|Open|Select)/u.test(task)) {
    return `For “${task}”, a changed prompt proves only this scope: ${effect} It does not perform the next feature change or save earlier running configuration. If the scope was wrong: ${recovery}`;
  }
  return `Do not continue merely because IOS accepted the line. Verify “${effect}”; if the wrong object changed, follow this narrow recovery: ${recovery}`;
};

const step = (
  id: string,
  phase: LabPhase,
  context: LabContext,
  command: string,
  task: string,
  why: string,
  effect: string,
  verify: string,
  recovery: string,
  options: StepOptions = {},
): LabContentStep => ({
  id,
  conceptId: `lab.${id}`,
  phase,
  context,
  command,
  task,
  why,
  hint1: options.hint1 ?? withoutPasteableCommand(why, command),
  hint2: options.hint2 ?? defaultHint2(context, command, task, why),
  effect,
  verify,
  interpretation: options.interpretation ?? defaultInterpretation(task, effect, verify),
  commonFailure: options.commonFailure ?? defaultCommonFailure(phase, task, effect, recovery),
  recovery,
  ...(options.nextContext ? { nextContext: options.nextContext } : {}),
  ...(options.nextHostname ? { nextHostname: options.nextHostname } : {}),
  ...(options.output ? { output: options.output } : {}),
  ...(options.sensitiveArgumentNames ? { sensitiveArgumentNames: options.sensitiveArgumentNames } : {}),
});

const seededSecret = (purpose: "local" | "radius", seed: number): string => {
  const prefix = purpose === "local" ? "LocalLab" : "RadiusLab";
  return `${prefix}-${1_000 + (Math.abs(Math.trunc(seed)) % 8_000)}!`;
};

const saveOutput = ["Destination filename [startup-config]?", "Building configuration...", "[OK]"] as const;

