export const createLabContent = (id: LabId, seed = 1): LabContentDefinition =>
  id === "router-foundation"
    ? createRouterFoundationContent(seed)
    : createSwitchFoundationContent(seed);

export const labContentDefinitions = [
  createRouterFoundationContent(),
  createSwitchFoundationContent(),
] as const;
